"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

/**
 * Input — reconciled 1:1 with the design source, Figma "KinetixUI" › UI Components ›
 * 01. Form Inputs › Input (node 54855:13836).
 *
 * Figma component property: state = Default | Focus | Error | Disabled.
 * Focus is the CSS `:focus-visible` pseudo-class and Disabled is the native
 * attribute; the `state` prop force-pins one for docs / snapshots, and
 * `state="Error"` sets `aria-invalid`. Focus uses the `--shadow-focus` token.
 *
 * Figma's component bundles a label + helper text; those live in the `Field`
 * composition (their colour tracks the control's state). This is the bare
 * control. Tokens: border `--muted-foreground`, focus `--ring`, error `--destructive`,
 * radius `--radius-field` (→ `--radius-sm`, Figma `input` = 4px), padding `--spacing-3`,
 * text = Body Medium (14 / 20, +0.25).
 *
 * It follows the text-entry state contract (TOKENS.md, "Text entry and navigation"):
 *
 *   rest       edge `--muted-foreground` at 80% — 3.4:1 light / 5.4:1 dark on a card, where `--input` was
 *              2.2:1 / 2.4:1 and was the only thing marking where the field is (SC 1.4.11)
 *   hover      a pointer that can hover: the edge steps to full `--muted-foreground`. Not on a focused,
 *              invalid, read-only or disabled field — hover never takes over a stronger state
 *   focus      `--action` edge + the `--shadow-focus` ring, the strongest signal, unchanged by the pointer
 *   invalid    `aria-invalid="true"` → `--destructive` edge and ring, which hover does not replace; the
 *              field's error text is the non-colour cue (SC 1.4.1)
 *   read-only  an inset `--muted` fill, full-strength text, no hover: readable and selectable, not editable
 *   disabled   `--opacity-disabled`, inert
 *
 * Motion: border-color, box-shadow and background-color over `duration-instant` with `ease-standard`.
 * Reduced motion collapses it (the library floor) and lands on the same end state.
 */
const inputVariants = cva(
  [
    "flex w-full border border-muted-foreground/80 bg-background px-3 py-3",
    "font-sans text-body-md text-foreground",
    "placeholder:text-muted-foreground",
    "outline-none transition-[border-color,box-shadow,background-color] duration-instant ease-standard",
    "[@media(hover:hover)]:enabled:hover:[&:not(:focus):not([aria-invalid=true]):not([readonly]):not([data-state=focus])]:border-muted-foreground",
    "[&[readonly]]:bg-muted",
    "focus-visible:border-action focus-visible:shadow-focus",
    "disabled:cursor-not-allowed disabled:opacity-disabled",
    "aria-[invalid=true]:border-destructive aria-[invalid=true]:focus-visible:border-destructive aria-[invalid=true]:focus-visible:shadow-focus-destructive",
  ],
  {
    variants: {
      state: {
        Default: "",
        Focus: "border-action shadow-focus",
        Error: "border-destructive",
        Disabled: "opacity-disabled pointer-events-none",
      },
      /** corner style — matches the design source's Corners property */
      corners: {
        sharp: "rounded-none",
        default: "rounded-field",
        rounded: "rounded-md",
        pill: "rounded-full px-4",
      },
    },
    defaultVariants: { state: "Default", corners: "default" },
  },
);

export interface InputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size">,
    VariantProps<typeof inputVariants> {}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, state, corners, type = "text", disabled, "aria-invalid": ariaInvalid, ...props }, ref) => (
    <input
      ref={ref}
      type={type}
      data-slot="input"
      data-state={state ? state.toLowerCase() : undefined}
      aria-invalid={ariaInvalid ?? (state === "Error" || undefined)}
      disabled={disabled || state === "Disabled"}
      className={cn(inputVariants({ state, corners }), className)}
      {...props}
    />
  ),
);
Input.displayName = "Input";

export { Input, inputVariants };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
